+                        currentValueUnmapped = null;
+                        next.collect(doc, bucket);
+                    }
+                } else if (missingBucket) {
+                    currentValueOrd = Long.MIN_VALUE;
+                    currentValueUnmapped = null;
+                    next.collect(doc, bucket);
+                }
